<script setup lang="ts">
import {ref} from 'vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
interface Question{key:string;label:string;source:string}
interface Diagnostic{id:number;revision:number;status:string;template_snapshot:{title:string;questions:Question[]}}
interface Finding{id:number;title:string;fact:string;category:string;presumed_cause:string;recommendation:string;observed_on:string;status:string;version:number;source_snapshot:{model_title:string;diagnostic_revision:number;question:Question;answer:{answer:string;note:string}|null}}
const props=defineProps<{missionId:number;active:boolean}>(),emit=defineEmits<{changed:[]}>()
const open=ref(false),editor=ref(false),busy=ref(false),lead=ref(false),error=ref(''),dialogError=ref(''),mode=ref('create'),confirmed=ref(false),key=ref(''),rows=ref<Finding[]>([]),sources=ref<Diagnostic[]>([]),selected=ref<Finding|null>(null),reading=ref<Finding|null>(null)
const categories:Record<string,string>={strength:'Point fort',improvement:'Point à améliorer',gap:'Écart',potential_nonconformity:'Non-conformité potentielle (à qualifier)'}
const form=ref({title:'',fact:'',category:'improvement',presumed_cause:'',recommendation:'',observed_on:'',diagnostic_id:0,question_key:''})
async function load(){busy.value=true;error.value='';try{const data=await request<{data:Finding[];can_lead:boolean}>(`/support/missions/${props.missionId}/findings`);rows.value=data.data;lead.value=data.can_lead;sources.value=[];if(lead.value){const d=await request<{diagnostics:Diagnostic[]}>(`/support/missions/${props.missionId}/diagnostics`);sources.value=d.diagnostics.filter(d=>['submitted','shared'].includes(d.status))}}catch(e){rows.value=[];sources.value=[];lead.value=false;reading.value=null;error.value=(e as Error).message}finally{busy.value=false}}
function edit(f?:Finding,share=false){selected.value=f||null;mode.value=share?'share':f?'edit':'create';dialogError.value='';confirmed.value=false;key.value=crypto.randomUUID();form.value={title:f?.title||'',fact:f?.fact||'',category:f?.category||'improvement',presumed_cause:f?.presumed_cause||'',recommendation:f?.recommendation||'',observed_on:f?.observed_on||new Date().toLocaleDateString('sv-SE',{timeZone:'Africa/Porto-Novo'}),diagnostic_id:0,question_key:''};editor.value=true}
function prefill(){const q=sources.value.find(d=>d.id===form.value.diagnostic_id)?.template_snapshot.questions.find(q=>q.key===form.value.question_key);if(q&&!form.value.title)form.value.title=q.label.slice(0,180)}
async function save(){busy.value=true;dialogError.value='';try{let path=`/support/missions/${props.missionId}/findings`,method='POST';let body:unknown={...form.value,request_key:key.value,confirmed:confirmed.value};if(mode.value==='edit'){path+='/'+selected.value!.id;method='PATCH';body={...form.value,version:selected.value!.version}}if(mode.value==='share'){path+=`/${selected.value!.id}/share`;body={version:selected.value!.version,confirmed:confirmed.value}}await request(path,method,body);await load();editor.value=false;emit('changed')}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><button class="button secondary" @click="open=true;load()">Constats du diagnostic</button>
<AppModal v-model="open" title="Constats de la mission" size="wide" :busy="busy"><div class="form-body"><p v-if="error" class="alert error" role="alert">{{error}}</p><p class="module-disclaimer">Un constat décrit un fait, pas une certification. Une cause présumée ne constitue pas une cause démontrée. Aucune non-conformité ni action n’est créée automatiquement.</p><button v-if="lead&&active" class="button primary" :disabled="!sources.length" @click="edit()">Créer un constat</button><p v-if="lead&&!sources.length">Soumettez un diagnostic pour disposer d’une source figée.</p><p v-if="!rows.length">Aucun constat visible dans votre périmètre.</p><article v-for="f in rows" :key="f.id" class="detail-card"><strong>{{f.title}}</strong><p>{{categories[f.category]}} · {{f.status==='shared'?'Partagé':'Brouillon privé'}} · {{f.observed_on}}</p><div class="heading-actions"><button class="button secondary small" @click="reading=f">Voir le constat</button><template v-if="lead&&active&&f.status==='draft'"><button class="button secondary small" @click="edit(f)">Modifier le constat</button><button class="button primary small" @click="edit(f,true)">Partager le constat</button></template></div></article><p class="module-disclaimer">Liaison M4 indisponible dans cette tranche : aucune action dupliquée ou simulée. Les preuves documentaires M3 restent à connecter.</p></div><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Fermer</button></template></AppModal>
<AppModal v-model="editor" :title="mode==='share'?'Partager le constat ?':mode==='edit'?'Modifier le brouillon':'Créer un constat'" :busy="busy" size="wide"><form id="finding-form" class="form-body correction-form" @submit.prevent="save"><p v-if="dialogError" class="alert error" role="alert">{{dialogError}}</p><template v-if="mode!=='share'"><template v-if="mode==='create'"><label>Diagnostic source<select v-model="form.diagnostic_id" required @change="form.question_key='' "><option :value="0" disabled>Choisir un diagnostic figé</option><option v-for="d in sources" :key="d.id" :value="d.id">{{d.template_snapshot.title}} · diagnostic r{{d.revision}} · {{d.status==='shared'?'Partagé':'Soumis, non partagé'}}</option></select></label><label>Question source<select v-model="form.question_key" required @change="prefill"><option value="" disabled>Choisir une question</option><option v-for="q in sources.find(d=>d.id===form.diagnostic_id)?.template_snapshot.questions||[]" :key="q.key" :value="q.key">{{q.label}}</option></select></label></template><label>Titre<input v-model="form.title" required maxlength="180"/></label><label>Description factuelle<textarea v-model="form.fact" required maxlength="5000" rows="4"/></label><label>Catégorie proposée<select v-model="form.category"><option v-for="(label,k) in categories" :key="k" :value="k">{{label}}</option></select></label><label>Cause présumée (hypothèse distincte du fait)<textarea v-model="form.presumed_cause" maxlength="3000"/></label><label>Recommandation<textarea v-model="form.recommendation" maxlength="3000"/></label><label>Date d’observation<input v-model="form.observed_on" type="date" required/></label></template><p v-else>Le constat et son instantané de source deviennent visibles à l’officine et sont figés. Le diagnostic source doit avoir été partagé au préalable. Vérifiez tous les commentaires avant cette opération.</p><label v-if="mode!=='edit'" class="checkbox-label"><input v-model="confirmed" type="checkbox" required/>Je confirme cette opération sans qualification réglementaire automatique.</label></form><template #footer><button class="button secondary" :disabled="busy" @click="editor=false">Annuler</button><button class="button primary" form="finding-form" type="submit" :disabled="busy">{{mode==='share'?'Confirmer le partage':'Enregistrer le brouillon'}}</button></template></AppModal>
<AppModal :model-value="!!reading" title="Constat et source conservée" size="wide" @update:model-value="reading=null"><div v-if="reading" class="form-body"><h3>{{reading.title}}</h3><p>{{categories[reading.category]}} · {{reading.observed_on}} · {{reading.status==='shared'?'Partagé et figé':'Brouillon'}}</p><h4>Fait observé</h4><p style="white-space:pre-wrap">{{reading.fact}}</p><h4>Cause présumée</h4><p style="white-space:pre-wrap">{{reading.presumed_cause||'Non renseignée'}}</p><h4>Recommandation</h4><p style="white-space:pre-wrap">{{reading.recommendation||'Non renseignée'}}</p><h4>Origine figée</h4><p>{{reading.source_snapshot.model_title}} · diagnostic r{{reading.source_snapshot.diagnostic_revision}}</p><p>{{reading.source_snapshot.question.label}}</p><p>Source : {{reading.source_snapshot.question.source||'Non renseignée'}}</p><p style="white-space:pre-wrap">Commentaire d’origine : {{reading.source_snapshot.answer?.note||'Non renseigné'}}</p></div><template #footer><button class="button secondary" @click="reading=null">Fermer</button></template></AppModal></template>
